const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
if(!reduced.matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const menuButton=document.querySelector('.menu-toggle'),menu=document.querySelector('#mobile-menu');menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')==='true';menuButton.setAttribute('aria-expanded',String(!open));menu.hidden=open});menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.hidden=true;menuButton.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.hidden=true;menuButton.setAttribute('aria-expanded','false')}});
const produce={tomato:{image:'tomatoes',alt:'色と形の異なる小玉トマト',badge:'17 VARIETIES',label:'01 / TOMATO COLLECTION',title:'小さな一粒に、<br>大きな個性。',description:'赤、黄、桃色、葡萄のような赤紫。<br>甘みも酸味も、形もいろいろ。<br>そのままでも、ひと皿の主役にも。',examples:[['アイコ','細長いプラム型。サラダや前菜に。'],['ピンキー','うす皮で、やわらかな口当たり。'],['サンマルツァーノ','加熱して旨みが立つ、ソースの味方。']]},greens:{image:'vegetables',alt:'トレビスやレタス、キャベツなどの西洋野菜',badge:'COLOR & TEXTURE',label:'02 / WESTERN VEGETABLES',title:'食卓に、<br>彩りと歯ざわり。',description:'赤紫の葉。くるんとした葉先。<br>ほろ苦さも、シャキッとした食感も。<br>いつもの料理に、新しい表情を。',examples:[['トレビス','赤紫の層と、心地よい苦味。'],['プンタレッラ','みずみずしい食感を楽しんで。'],['サボイキャベツ','縮れた葉を、煮込み料理に。']]},herbs:{image:'herbs',alt:'バジルやローズマリーなどのフレッシュハーブ',badge:'FRESH AROMAS',label:'03 / FRESH HERBS',title:'ひと枝で、<br>ごちそうの香り。',description:'トマトにバジル。魚料理にディル。<br>いつものひと皿を、ぐっと豊かに。<br>仕上げの香りまで、畑から。',examples:[['バジル','トマトやソース、料理の仕上げに。'],['ディル','魚料理、ピクルス、冷菜に。'],['ローズマリー','肉や芋のローストに。']]}};
const tabs=[...document.querySelectorAll('[role=tab]')];function selectTab(button){const d=produce[button.dataset.kind];tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===button));t.tabIndex=t===button?0:-1});document.querySelector('#produce-panel').setAttribute('aria-labelledby',button.id);const photo=document.querySelector('#produce-photo');photo.src=`assets/${d.image}-v2.webp`;photo.removeAttribute('srcset');photo.alt=d.alt;document.querySelector('#produce-badge').textContent=d.badge;document.querySelector('#produce-label').textContent=d.label;document.querySelector('#produce-title').innerHTML=d.title;document.querySelector('#produce-description').innerHTML=d.description;document.querySelector('#produce-examples').replaceChildren(...d.examples.map(([name,description])=>{const p=document.createElement('p'),b=document.createElement('b'),s=document.createElement('span');b.textContent=name;s.textContent=description;p.append(b,s);return p}));}tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectTab(t));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();selectTab(tabs[n])}})});
const dialog=document.querySelector('#photo-dialog');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dialog-title').textContent=b.dataset.title;const img=document.querySelector('#dialog-photo');dialog.classList.toggle("crop-left",b.dataset.crop==="left");img.src=`assets/${b.dataset.photo}-v2.webp`;img.alt=b.dataset.title+'のご紹介';dialog.showModal()}));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let ticking=false;const hero=document.querySelector('.hero'),photoLayer=document.querySelector('.hero-photo');function parallax(){if(!hero||!photoLayer){ticking=false;return}if(!reduced.matches&&window.innerWidth>760&&window.scrollY<hero.offsetHeight){photoLayer.style.transform=`translateY(${Math.min(window.scrollY*.14,90)}px)`}else photoLayer.style.transform='';ticking=false}window.addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(parallax);ticking=true}},{passive:true});reduced.addEventListener('change',()=>{document.documentElement.classList.toggle('js-motion',!reduced.matches);document.querySelectorAll('.reveal').forEach(e=>e.classList.add('visible'));parallax()});

const opening=document.querySelector('.opening');
if(opening){const replay=document.querySelector('#opening-replay'),skip=document.querySelector('#opening-skip');opening.querySelectorAll('.opening-menu>a').forEach((a,i)=>a.style.setProperty('--menu-order',i));let openingTimer;function finishOpening(){opening.classList.remove('is-playing');clearTimeout(openingTimer);skip.hidden=true}function playOpening(){finishOpening();if(reduced.matches)return;skip.hidden=false;void opening.offsetWidth;opening.classList.add('is-playing');openingTimer=setTimeout(finishOpening,document.body.classList.contains("photo-home")?3800:7200)}replay.addEventListener('click',()=>{opening.scrollIntoView({behavior:'instant',block:'start'});playOpening()});skip.addEventListener('click',finishOpening);opening.querySelectorAll('a').forEach(a=>a.addEventListener('click',finishOpening));reduced.addEventListener('change',finishOpening);playOpening();}
